// Step 2: Evidence-Grounded Outreach Drafter & Compliance Guard
const body = $input.first().json.body || $input.first().json;

const domain = (body.domain || '').trim().toLowerCase();
const businessName = body.business_name || domain;
const contactEmail = (body.contact_email || '').trim().toLowerCase();
const auditFindings = body.audit_findings || [];
const offeredService = body.offered_service || 'Integrated AI Client Operations System';
const postalAddress = body.postal_address || 'Agency OS Services, 100 Congress Ave, Suite 2000, Austin, TX 78701, USA';

if (!domain || !contactEmail) {
  throw new Error('Validation failed: Both "domain" and "contactEmail" are strictly required.');
}

// Format primary observation
let observation = 'noted opportunities to optimize your digital customer conversion flow';
if (Array.isArray(auditFindings) && auditFindings.length > 0) {
  observation = `noted that ${auditFindings[0].toLowerCase()}`;
}

// Draft personalized message
const subject = `Quick observation regarding ${businessName}`;
const bodyText = `Hi ${businessName} Team,\n\nWhile reviewing ${domain} today, I ${observation}.\n\nWe help commercial firms install an ${offeredService} that resolves these issues and recaptures lost prospect inquiries automatically.\n\nWould you be open to a brief 10-minute discovery call this Thursday to explore if this fits your current priorities?\n\nBest regards,\nAgency OS Client Solutions Team\n\n---\n${postalAddress}\nTo opt out, reply with 'unsubscribe'.`;

// Compliance & Safety Verification
const hasOptOut = /unsubscribe/i.test(bodyText);
const hasPostal = bodyText.includes(postalAddress);
const isCompliant = hasOptOut && hasPostal;

return [{
  json: {
    status: 'DRAFT_READY',
    domain: domain,
    recipient_email: contactEmail,
    subject: subject,
    body_text: bodyText,
    compliance: {
      can_spam_compliant: isCompliant,
      has_unsubscribe: hasOptOut,
      has_physical_address: hasPostal
    },
    approval_state: 'AWAITING_CEO_APPROVAL',
    can_send_live: false,
    drafted_at: new Date().toISOString()
  }
}];
